import { hashIdentifier } from '../../crypto/sha256';

// A deliberately tiny group for the theory page's worked example: the order-509 subgroup of
// integers mod the safe prime p = 1019 = 2 * 509 + 1, generated by g = 4. Small enough to follow
// by hand, and it obeys the same algebra as ristretto255 (which has order about 2^252).
// Never use it for anything real: logarithms in a group this small are trivial.

export const TOY_P = 1019n;
export const TOY_ORDER = 509n;
export const TOY_G = 4n;

export function toyPow(base: bigint, exponent: bigint): bigint {
  let result = 1n;
  let b = base % TOY_P;
  let e = exponent;
  while (e > 0n) {
    if (e & 1n) result = (result * b) % TOY_P;
    b = (b * b) % TOY_P;
    e >>= 1n;
  }
  return result;
}

/** H(x) = g^e with e drawn from SHA-256(x): a stand-in for hash-to-group. */
export function toyHash(value: string): bigint {
  const digest = hashIdentifier(value);
  const n = BigInt(((digest[0]! << 24) | (digest[1]! << 16) | (digest[2]! << 8) | digest[3]!) >>> 0);
  return toyPow(TOY_G, (n % (TOY_ORDER - 1n)) + 1n);
}
